contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 addAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (addAmount)); require(addAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= addAmount);
        require(addAmount > 0);

        c.addToBalance{value: addAmount}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;

        bool reverted;
        c.withdrawBalance(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.getBalance(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;

        assert(
            reverted
                ? balBefore > cBalBefore && balAfter == balBefore && cBalAfter == cBalBefore
                : balBefore <= cBalBefore && balAfter == 0 && cBalAfter == cBalBefore - balBefore
        );
    }

    receive() external payable {}
}

