pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 addAmount) internal {
        addAmount = bound(addAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= addAmount);
        vm.assume(addAmount > 0);
        try c.addToBalance{value: addAmount}() {} catch { return; }
        uint256 balBefore;
        try c.getBalance(address(this)) returns (uint256 __r) { balBefore = __r; } catch { return; }
        uint256 cBalBefore = address(c).balance;
        bool reverted;
        try c.withdrawBalance() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 balAfter;
        try c.getBalance(address(this)) returns (uint256 __r) { balAfter = __r; } catch { return; }
        uint256 cBalAfter = address(c).balance;
        assertTrue(reverted
                ? balBefore > cBalBefore && balAfter == balBefore && cBalAfter == cBalBefore
                : balBefore <= cBalBefore && balAfter == 0 && cBalAfter == cBalBefore - balBefore);
    }

    function testFuzz_run(uint256 addAmount) public {
        _run(addAmount);
    }

    receive() external payable {}
}
